sys.modules['qa_test_module_cov'] = mod
spec.loader.exec_module(mod)

obj = mod.TestDiscretisationProcessModelCallCoverageQA()

prefixes = (
    'pybamm.discretisations.discretisation.',
    'pybamm.spatial_methods.',
    'pybamm.models.base_model.',
    'pybamm.models.event.',
    'pybamm.expression_tree.',
)

covered = set()
active_target_frames = set()

def rel_file(path: str):
    p = Path(path).resolve()
    try:
        return p.relative_to(repo).as_posix()
    except Exception:
        return None

def tracer(frame, event, arg):
    if event not in ('call', 'return', 'exception'):
        return tracer

    frame_id = id(frame)

    if event == 'call':
        module = frame.f_globals.get('__name__', '')
        qualname = frame.f_code.co_qualname
        trace_name = f"{module}.{qualname}"

        if trace_name == 'pybamm.discretisations.discretisation.Discretisation.process_model':
            active_target_frames.add(frame_id)

        if active_target_frames:
            file_rel = rel_file(frame.f_code.co_filename)
            if file_rel and file_rel.startswith('src/pybamm') and not file_rel.startswith('src/pybamm/tests'):
                if '<' not in frame.f_code.co_name and '<' not in qualname:
                    if trace_name.startswith(prefixes):
                        covered.add((file_rel, trace_name))

    else:
        if frame_id in active_target_frames:
            active_target_frames.remove(frame_id)

    return tracer

sys.settrace(tracer)
try:
    for i in range(1, 11):
        getattr(obj, f'test_case_{i:02d}')()
finally:
    sys.settrace(None)

answer = {
    'covered_functions': [
        {'file': file_rel, 'func': func_name}
        for file_rel, func_name in sorted(covered)
    ]
}

output_path.write_text(json.dumps(answer, indent=2) + '\n', encoding='utf-8')

# Validate JSON written
json.loads(output_path.read_text(encoding='utf-8'))
print(f"wrote {len(answer['covered_functions'])} covered functions")
